<?php\n/**\n * Script individual para scraping principal\n * Este script executa apenas o scraping principal do site CCCRJ\n */\n\n// Incluir o arquivo com a definição da classe (sem execução automática)\n$content = file_get_contents('scraper.php');\n\n// Remover a execução automática no final do arquivo\n$content = preg_replace('/\\?>.*\\$scraper = new CCCRJScraper\\(\\);.*\\$scraper->run\\(\\);/s', '?>', $content);\n\n// Salvar temporariamente\nfile_put_contents('temp_scraper.php', $content);\n\n// Incluir a classe\ninclude_once 'temp_scraper.php';\n\n// Criar e executar o scraper\n$scraper = new CCCRJScraper();\n$scraper->run();\n\n// Remover o arquivo temporário\nunlink('temp_scraper.php');\n?>